#pragma once

#include "defender/entities/Types.hpp"
#include "defender/ui/Icon.hpp"

#include <SFML/Graphics/Color.hpp>
#include <SFML/Graphics/Rect.hpp>
#include <SFML/Graphics/RenderTarget.hpp>
#include <SFML/System/Vector2.hpp>

#include <string>
#include <string_view>
#include <vector>

/// Drawing helpers for the interface: pixel font, icons, panels.
/// Textures come from assets/sprites/ui/ (generated by `make sprites`).
namespace defender::ui
{

/// Glyph cell of font.png: 5x7 glyphs, 1 px spacing, row 7 for the cedilla.
inline constexpr int GLYPH_W = 6;
inline constexpr int GLYPH_H = 8;

/// Pixel size of `text` drawn at `scale` (UTF-8, '\n' starts a new line).
[[nodiscard]] sf::Vector2f measureText(std::string_view text, float scale = 2.f);

/// Draws UTF-8 text (ASCII + é è ê à â ç ù û ô î). Top-left at `position`.
/// A 1-scaled-pixel dark shadow keeps it readable on any background.
void drawText(sf::RenderTarget& target, std::string_view text, sf::Vector2f position,
              float scale = 2.f, sf::Color color = sf::Color::White, bool shadow = true);

/// Splits `text` into lines no wider than `maxWidth` pixels.
[[nodiscard]] std::vector<std::string> wrapText(std::string_view text, float maxWidth,
                                                float scale = 2.f);

/// Draws an icon (16x16 * scale), top-left at `position`. `tint` darkens it.
void drawIcon(sf::RenderTarget& target, Icon icon, sf::Vector2f position, float scale = 2.f,
              sf::Color tint = sf::Color::White);

/// Draws the first frame of a tower sprite (32x48) fitted in `box`.
void drawTowerIcon(sf::RenderTarget& target, TowerType type, const sf::FloatRect& box,
                   sf::Color tint = sf::Color::White);

/// Filled rectangle with an optional border.
void drawPanel(sf::RenderTarget& target, const sf::FloatRect& box, sf::Color fill,
               sf::Color border = sf::Color::Transparent, float borderWidth = 2.f);

/// Thick line between two points.
void drawLine(sf::RenderTarget& target, sf::Vector2f from, sf::Vector2f to, float width,
              sf::Color color);

// Interface colors
inline const sf::Color PANEL{24, 22, 32, 235};
inline const sf::Color PANEL_LIGHT{44, 40, 58, 255};
inline const sf::Color BORDER{110, 100, 140};
inline const sf::Color GOLD{245, 197, 66};
inline const sf::Color TEXT_DIM{150, 146, 165};
inline const sf::Color GOOD{122, 216, 96};
inline const sf::Color BAD{232, 72, 88};

}  // namespace defender::ui
